label{display:block;font-size:14px;font-weight:750;margin:8px 0 5px}input,select,textarea{width:100%;padding:11px;border:1px solid #d8c6bb;border-radius:10px;background:#fff;font:inherit}textarea{min-height:76px}.check{display:flex;align-items:center;gap:7px}.check input{width:auto}
button,.button{border:0;border-radius:10px;padding:10px 14px;background:var(--o);color:#fff;font-weight:800;text-decoration:none;cursor:pointer}.secondary{background:#fff1e8;color:var(--od)}.danger{background:var(--danger)}.success{background:var(--green)}
.message{padding:13px;border-radius:10px;background:#e9f8ee;color:var(--green)}.error{background:#fff0ee;color:var(--danger)}details.facility{background:#fff;border:1px solid var(--line);border-radius:18px;margin-bottom:18px;overflow:hidden}details.facility>summary{cursor:pointer;list-style:none;padding:20px;display:flex;justify-content:space-between;gap:15px;align-items:center}details.facility>summary::-webkit-details-marker{display:none}.content{padding:0 20px 20px}.badge{display:inline-block;padding:5px 9px;border-radius:999px;background:#eef7f1;color:var(--green);font-size:12px;font-weight:800}.tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:20px}.subcard{border:1px solid var(--line);border-radius:14px;padding:15px}.item{padding:12px 0;border-top:1px solid #eee}.item:first-child{border-top:0}.compact{display:grid;grid-template-columns:1fr 1fr;gap:8px}.archives{border-left:4px solid #8b766a}.module-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.module{border:1px solid var(--line);border-radius:12px;padding:12px}
